// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.ResourceCategoryimport com.roshan.persona.system.util.HardwareExceptionMapper/** * NOUS — Timer Handler (Module 10 v2 — Step 10.8). * * Sets countdown timers via Android's `AlarmClock.ACTION_SET_TIMER` intent. * * ## Behavior (per strategy §"Time / Alarms") * *  - Launches the system clock app's "set timer" UI pre-filled with *    duration/label. *  - The user confirms the timer in the clock app. *  - Requires no special permission — any app can fire the AlarmClock intent. * * ## Exception handling (Review 2 Fix C) * *  - `ActivityNotFoundException` (no clock app installed) → mapped to *    `Hardware.Unsupported` with message "No timer app installed". * * ## Reversibility * * Not reversible — Android's `AlarmClock` intent API has no * `ACTION_CANCEL_TIMER`. The clock app owns the timer, so cancellation * requires the user to dismiss it manually. * * The [cancel] method opens the timer list (action * `android.intent.action.SHOW_TIMERS`) so the user can find + dismiss the * timer they just set. See [AlarmHandler] class KDoc for the full rationale * (programmatic cancellation would require `AlarmManager.setExact` against * a NOUS-owned `PendingIntent`, ruled out by the strategy). * * ## Resource category * * Timers use [ResourceCategory.APP] — fires an intent that launches an app. * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Scope — Timers</a> */class TimerHandler(    private val timerService: TimerService,) : StatelessSystemOperationHandler<SystemOperation.SetTimer>() {    override val id: String = "timer"    override val displayName: String = "Timer Setter"    override val requiredPermissions: Set<String> = setOf(        "com.android.alarm.permission.SET_ALARM",    )    override val resourceCategory: ResourceCategory = ResourceCategory.APP    override fun isAvailable(): Boolean = true  // most devices have a clock app    override suspend fun execute(operation: SystemOperation.SetTimer): Result<Unit> {        // Validate duration — must be positive and reasonable (max 24 hours).        if (operation.durationSeconds <= 0) {            return Result.Failure(                error = AppError.Hardware.Unsupported(                    resource = "timer:duration:${operation.durationSeconds}",                    cause = null,                ),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }        if (operation.durationSeconds > MAX_TIMER_SECONDS) {            return Result.Failure(                error = AppError.Hardware.Unsupported(                    resource = "timer:duration_exceeds_24h",                    cause = null,                ),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }        return HardwareExceptionMapper.withMappingSync("timer") {            val success = timerService.setTimer(                durationSeconds = operation.durationSeconds,                label = operation.label,                skipUi = false,  // show the timer UI so user can see/cancel            )            if (success) {                Result.Success(Unit, CorrelationId.generate(), 0)            } else {                Result.Failure(                    error = AppError.Hardware.Unsupported("timer_app"),                    correlationId = CorrelationId.generate(),                    durationNanos = 0,                )            }        }    }    /**     * Best-effort cancel — opens the system timer list UI so the user can     * manually dismiss the timer they just set.     *     * Android's `AlarmClock` intent API has no `ACTION_CANCEL_TIMER`, so a     * true programmatic cancel is not possible. See class KDoc + [AlarmHandler]     * KDoc for the full rationale.     *     * @return `true` if the timer list UI was launched successfully.     */    suspend fun cancel(): Boolean {        return try {            timerService.showTimers()        } catch (t: Throwable) {            Timber.tag("TimerHandler").w(t, "cancel failed — could not open timer list")            false        }    }    private companion object {        /** Max timer duration = 24 hours (Android clock app limit). */        const val MAX_TIMER_SECONDS = 24L * 60 * 60    }}
